"""Current Windows boot/AC/USB binding + three fresh samples. No shutdown here."""
from pathlib import Path
import json,time,sys,base64,gzip,datetime
from windows_transport import run,command
w=Path(__file__).resolve().parent;s=(w/'Read-HWiNFO-Temperatures.ps1').read_bytes();b=base64.b64encode(gzip.compress(s,mtime=0)).decode();ps="$b=[Convert]::FromBase64String('"+b+"');$m=New-Object IO.MemoryStream(,$b);$g=New-Object IO.Compression.GZipStream($m,[IO.Compression.CompressionMode]::Decompress);$r=New-Object IO.StreamReader($g,[Text.Encoding]::UTF8);try{& ([scriptblock]::Create($r.ReadToEnd()))}finally{$r.Dispose();$g.Dispose();$m.Dispose()}"
meta="$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[pscustomobject]@{Computer=$env:COMPUTERNAME;BootUtc=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime().ToString('o');PowerOnline=@(Get-CimInstance -Namespace root\\WMI -ClassName BatteryStatus|ForEach-Object {$_.PowerOnline});USB=@(Get-Disk|Where-Object {$_.BusType -eq 'USB'}|Select-Object FriendlyName,SerialNumber,Size);USBPnP=@(Get-CimInstance Win32_DiskDrive|Where-Object {$_.InterfaceType -eq 'USB'}|Select-Object Model,PNPDeviceID);USBVolumes=@(Get-CimInstance Win32_LogicalDisk|Where-Object {$_.DriveType -eq 2}|Select-Object DeviceID,VolumeSerialNumber,FileSystem)}|ConvertTo-Json -Depth 4 -Compress"
r=run(meta);assert r.returncode==0,r.stderr;x=json.loads(r.stdout);assert x['Computer']=='BOGEBEARSP7' and x['PowerOnline'] and all(v is True for v in x['PowerOnline']);assert any(q['Size']==31042043904 and q['FriendlyName']=='Verbatim STORE N GO' for q in x['USB']) and any('072128E995155590&0' in q['PNPDeviceID'] for q in x['USBPnP']) and any(q['VolumeSerialNumber']=='C48CB988' and q['FileSystem']=='FAT32' for q in x['USBVolumes']),x
result={'schema':'sp7-current-pre-shutdown-temperature-series-v1','metadata':x,'samples':[],'shutdown_performed':False,'final_fresh_remote_check_still_required':True,'started_epoch':time.time()};p=w/'preboot-temperature-series.json'
for i in range(3):
 r=run(ps);assert r.returncode==0,r.stderr;t=json.loads(r.stdout);result['samples'].append(t);p.write_text(json.dumps(result,indent=2)+'\n');assert t['CompletePackageAndFourCores'] is True and t['StrictlyBelow60'] is True,'Temperature unknown/hot; stop, cooldown rule applies'
 if i:assert t['PollUnixSeconds']>result['samples'][i-1]['PollUnixSeconds'],'Not an independent fresh HWiNFO poll'
 print(json.dumps({'sample':i+1,'utc':t['Utc'],'temperatures':[(a['Label'],a['Celsius']) for a in t['Rows'] if a['Label']=='CPU Package' or a['Label'] in ['Core 0','Core 1','Core 2','Core 3']]}),flush=True)
 if i<2:time.sleep(2.3)
r=run(meta);assert r.returncode==0,r.stderr;y=json.loads(r.stdout);assert y['Computer']==x['Computer'] and y['BootUtc']==x['BootUtc'] and y['PowerOnline'] and all(y['PowerOnline']);result.update(complete=True,finished_epoch=time.time());p.write_text(json.dumps(result,indent=2)+'\n');print('Three fresh below60 samples, same Windows boot and external power confirmed; no shutdown yet',flush=True)
